<template>
  <div class="article-management">
    <h2>卫星地面融合网络社区-文章管理</h2>

    <!-- 搜索和筛选 -->
    <el-card class="filter-card">
      <el-form :inline="true" :model="filterForm" class="filter-form">
        <el-form-item label="关键词">
          <el-input v-model="filterForm.keyword" placeholder="搜索标题" clearable></el-input>
        </el-form-item>
        <el-form-item label="分类">
          <el-select v-model="filterForm.categoryId" placeholder="全部分类" clearable>
            <el-option :key="0" :label="'(不分类)'" :value="0"></el-option>
            <el-option v-for="cat in categories" :key="cat.id" :label="cat.categoryname" :value="cat.id"></el-option>
          </el-select>
        </el-form-item>
        <el-form-item>
          <el-button type="primary" @click="loadArticles">搜索</el-button>
          <el-button @click="resetFilter">重置</el-button>
        </el-form-item>
      </el-form>
    </el-card>

    <!-- 文章列表 -->
    <el-card>
      <el-table :data="articles" style="width: 100%" v-loading="loading">
        <el-table-column prop="id" label="ID" width="60"></el-table-column>
        <el-table-column prop="title" label="标题" show-overflow-tooltip>
          <template slot-scope="scope">
            <el-link type="primary" @click="viewArticle(scope.row.id)">{{ scope.row.title }}</el-link>
          </template>
        </el-table-column>
        <el-table-column prop="author" label="作者" width="100">
          <template slot-scope="scope">
            {{ scope.row.author ? scope.row.author.nickname : '-' }}
          </template>
        </el-table-column>
        <el-table-column prop="category" label="分类" width="120">
          <template slot-scope="scope">
            {{ scope.row.category ? scope.row.category.categoryname : '-' }}
          </template>
        </el-table-column>
        <el-table-column prop="viewCounts" label="浏览量" width="80"></el-table-column>
        <el-table-column prop="commentCounts" label="评论数" width="80"></el-table-column>
        <el-table-column prop="createDate" label="发布时间" width="160">
          <template slot-scope="scope">
            {{ formatDate(scope.row.createDate) }}
          </template>
        </el-table-column>
        <el-table-column label="操作" width="150" fixed="right">
          <template slot-scope="scope">
            <el-button type="text" size="small" @click="viewArticle(scope.row.id)">查看</el-button>
            <el-button type="text" size="small" @click="editArticle(scope.row.id)">编辑</el-button>
            <el-button type="text" size="small" class="danger-text" @click="deleteArticle(scope.row)">删除</el-button>
          </template>
        </el-table-column>
      </el-table>

      <!-- 分页 -->
      <el-pagination
        @current-change="handlePageChange"
        :current-page="pagination.pageNumber"
        :page-size="pagination.pageSize"
        :total="pagination.total"
        layout="total, prev, pager, next"
        style="margin-top: 20px; text-align: right;"
      ></el-pagination>
    </el-card>

    <!-- 删除确认对话框 -->
    <el-dialog title="确认删除" :visible.sync="deleteDialogVisible" width="400px">
      <p>确定要删除文章「{{ deleteTarget.title }}」吗？此操作不可恢复。</p>
      <span slot="footer">
        <el-button @click="deleteDialogVisible = false">取消</el-button>
        <el-button type="danger" @click="confirmDelete">删除</el-button>
      </span>
    </el-dialog>
  </div>
</template>

<script>
import { getArticles, deleteArticle as deleteArticleApi } from '@/api/article'
import { getAllCategorys } from '@/api/category'

export default {
  name: 'ArticleManagement',
  data() {
    return {
      articles: [],
      categories: [],
      loading: false,
      filterForm: {
        keyword: '',
        categoryId: null
      },
      pagination: {
        pageNumber: 1,
        pageSize: 10,
        total: 0
      },
      deleteDialogVisible: false,
      deleteTarget: {
        id: null,
        title: ''
      }
    }
  },
  created() {
    this.loadArticles()
    this.loadCategories()
  },
  methods: {
    async loadArticles() {
      this.loading = true
      try {
        const params = {
          pageNumber: this.pagination.pageNumber,
          pageSize: this.pagination.pageSize,
          name: 'a.createDate',
          sort: 'desc'
        }
        if (this.filterForm.categoryId) {
          params.categoryId = this.filterForm.categoryId
        }

        const res = await getArticles(this.filterForm, params)
        this.articles = res.data || []
        this.pagination.total = res.data ? res.data.length : 0
      } catch (error) {
        this.$message.error('加载文章列表失败')
      } finally {
        this.loading = false
      }
    },
    async loadCategories() {
      try {
        const res = await getAllCategorys()
        this.categories = res.data || []
      } catch (error) {
        console.error('加载分类失败:', error)
      }
    },
    handlePageChange(page) {
      this.pagination.pageNumber = page
      this.loadArticles()
    },
    resetFilter() {
      this.filterForm = {
        keyword: '',
        categoryId: null
      }
      this.pagination.pageNumber = 1
      this.loadArticles()
    },
    viewArticle(id) {
      this.$router.push(`/view/${id}`)
    },
    editArticle(id) {
      this.$router.push(`/write/${id}`)
    },
    deleteArticle(article) {
      this.deleteTarget = {
        id: article.id,
        title: article.title
      }
      this.deleteDialogVisible = true
    },
    async confirmDelete() {
      try {
        await deleteArticleApi(this.deleteTarget.id)
        this.$message.success('删除成功')
        this.deleteDialogVisible = false
        this.loadArticles()
      } catch (error) {
        this.$message.error('删除失败')
      }
    },
    formatDate(date) {
      if (!date) return '-'
      return date.substring(0, 19).replace('T', ' ')
    }
  }
}
</script>

<style scoped>
.article-management {
  padding: 20px;
}

.article-management h2 {
  margin-bottom: 20px;
  font-size: 24px;
  color: #303133;
}

.filter-card {
  margin-bottom: 20px;
}

.danger-text {
  color: #F56C6C;
}

.danger-text:hover {
  color: #f66;
}

/* 手机端适配 */
@media screen and (max-width: 767px) {
  .article-management {
    padding: 10px;
  }

  .article-management h2 {
    font-size: 18px;
    margin-bottom: 15px;
  }

  .filter-card {
    margin-bottom: 15px;
  }

  .el-table {
    font-size: 12px;
  }

  .el-table .cell {
    padding: 8px 4px;
  }
}

/* 平板端适配 */
@media screen and (min-width: 768px) and (max-width: 1024px) {
  .article-management {
    padding: 15px;
  }

  .article-management h2 {
    font-size: 20px;
  }

  .el-table {
    font-size: 13px;
  }
}
</style>



